<script setup lang="ts">
import type { InboxMessage } from '~/composables/useMailboxState'

const route = useRoute()
const { isLoggedIn, openLogin } = useAppState()
const { messages, markRead, markAllRead, deleteMessage, deleteReadMessages, claimMailReward } = useMailboxState()
const selectedMessage = ref<InboxMessage | null>(null)
const filter = ref<'all' | 'system' | 'event'>('all')
const loadingKey = ref('')
const notice = ref('')
const filteredMessages = computed(() => filter.value === 'all' ? messages.value : messages.value.filter(message => message.type === filter.value))
const typeLabel = { system: '系統通知', event: '營運公告', deposit: '帳務' }
const walletSymbol = { gold: '金', silver: '銀', bronze: '銅' }

function openMessage(message: InboxMessage) { markRead(message.id); selectedMessage.value = message }
function removeSelectedMessage() { if (!selectedMessage.value) return; deleteMessage(selectedMessage.value.id); selectedMessage.value = null; notice.value = '信件已刪除' }
async function runMock(key: string, action: () => number | boolean, successText: string) {
  loadingKey.value = key
  await new Promise(resolve => setTimeout(resolve, 700))
  const result = action()
  loadingKey.value = ''
  notice.value = result ? successText : '目前沒有可領取項目'
}
</script>

<template>
  <div class="lobby-page mailbox-page px-4 py-5">
    <template v-if="!isLoggedIn"><div class="card-purple p-8 text-center max-w-sm mx-auto mt-8"><div class="text-5xl mb-4">📬</div><h1 class="text-xl font-black mb-2">信箱</h1><p class="text-sm mb-5" style="color:var(--color-text-muted);">登入後即可查看系統訊息與領取信件附件</p><button class="btn-gold w-full justify-center" @click="openLogin(route.fullPath)">立即登入 / 註冊</button></div></template>
    <template v-else>
      <h1 class="section-title mb-4">信箱</h1>
      <p v-if="notice" class="mail-notice" aria-live="polite">{{ notice }}</p>

      <div class="mail-toolbar"><div><button v-for="item in ([['all','全部'],['event','營運公告'],['system','系統通知']] as const)" :key="item[0]" :class="{ active: filter === item[0] }" @click="filter = item[0]">{{ item[1] }}</button></div><div><button @click="markAllRead(); notice = '全部信件已標示為已讀'">全部已讀</button><button @click="deleteReadMessages(); selectedMessage = null; notice = '已讀信件已刪除'">刪除已讀</button></div></div>
      <div class="mail-layout"><section class="mail-list"><button v-for="message in filteredMessages" :key="message.id" class="mail-row" :class="{ read: message.read, active: selectedMessage?.id === message.id }" @click="openMessage(message)"><i /><div><div><span>{{ typeLabel[message.type] }}</span><time>{{ message.time }}</time></div><strong>{{ message.title }}</strong><p>{{ message.preview }}</p><small v-if="message.reward" :class="{ claimed: message.reward.claimed }">{{ message.reward.claimed ? '附件已領取' : `附件：${message.reward.label}` }}</small></div></button><div v-if="!filteredMessages.length" class="mail-empty">目前沒有信件</div></section>
        <aside class="mail-detail" :class="{ open: selectedMessage }"><template v-if="selectedMessage"><button class="detail-close" @click="selectedMessage = null">×</button><p>{{ typeLabel[selectedMessage.type] }}・{{ selectedMessage.time }}</p><h2>{{ selectedMessage.title }}</h2><div class="detail-body">{{ selectedMessage.body }}</div><div v-if="selectedMessage.reward" class="mail-attachment"><span>{{ walletSymbol[selectedMessage.reward.wallet] }}</span><div><strong>{{ selectedMessage.reward.label }}</strong><small>{{ selectedMessage.reward.claimed ? '已完成領取' : '領取後立即加入錢包' }}</small></div><button :disabled="selectedMessage.reward.claimed || loadingKey === `mail-${selectedMessage.id}`" @click="runMock(`mail-${selectedMessage.id}`, () => claimMailReward(selectedMessage.id), '附件已領取並更新餘額')">{{ loadingKey === `mail-${selectedMessage.id}` ? '領取中…' : selectedMessage.reward.claimed ? '已領取' : '領取' }}</button></div><button class="delete-mail" @click="removeSelectedMessage">刪除此信件</button></template><div v-else class="detail-empty"><span>✉</span><strong>選擇一封信件</strong><small>內容與附件會顯示在這裡</small></div></aside>
      </div>
    </template>
  </div>
</template>

<style scoped>
.mailbox-page{max-width:1180px;margin:0 auto}.gift-toolbar p{margin:0;color:var(--color-gold);font-size:9px;font-weight:900;letter-spacing:.18em}.mail-notice{padding:9px 12px;border:1px solid rgba(74,222,128,.25);border-radius:9px;color:#86efac;background:rgba(74,222,128,.08);font-size:10px}.mail-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:10px}.mail-toolbar>div{display:flex;gap:5px;overflow:auto}.mail-toolbar button{padding:7px 9px;border:1px solid var(--color-border);border-radius:8px;color:var(--color-text-muted);background:rgba(168,85,247,.05);font-size:9px;font-weight:800;white-space:nowrap}.mail-toolbar button.active{color:var(--color-gold);border-color:rgba(245,200,66,.3)}.mail-layout{display:grid;grid-template-columns:minmax(300px,.9fr) 1.1fr;min-height:490px;border:1px solid var(--color-border);border-radius:18px;overflow:hidden;background:rgba(15,0,32,.45)}.mail-list{border-right:1px solid var(--color-border)}.mail-row{position:relative;width:100%;display:grid;grid-template-columns:7px 1fr;gap:9px;padding:14px;border-bottom:1px solid rgba(168,85,247,.11);color:#fff;background:transparent;text-align:left}.mail-row:hover,.mail-row.active{background:rgba(168,85,247,.09)}.mail-row.read{opacity:.64}.mail-row>i{width:6px;height:6px;margin-top:7px;border-radius:50%;background:var(--color-purple-light)}.mail-row.read>i{background:transparent}.mail-row>div>div{display:flex;justify-content:space-between}.mail-row div span,.mail-row time{color:var(--color-purple-light);font-size:8px;font-weight:900}.mail-row time{color:var(--color-text-muted)}.mail-row strong{display:block;margin:4px 0;font-size:12px}.mail-row p{margin:0;overflow:hidden;color:var(--color-text-muted);font-size:9px;text-overflow:ellipsis;white-space:nowrap}.mail-row small{display:inline-block;margin-top:7px;padding:3px 6px;border-radius:6px;color:#fde68a;background:rgba(245,200,66,.1);font-size:8px}.mail-row small.claimed{color:var(--color-text-muted);background:rgba(255,255,255,.05)}.mail-detail{position:relative;padding:26px}.detail-close{display:none;position:absolute;right:15px;top:12px;color:var(--color-text-muted);background:none;font-size:23px}.mail-detail>p{margin:0;color:var(--color-purple-light);font-size:9px;font-weight:800}.mail-detail h2{margin:7px 0 18px;font-size:23px}.detail-body{min-height:170px;padding:17px;border:1px solid rgba(255,255,255,.07);border-radius:12px;color:var(--color-text-muted);background:rgba(0,0,0,.15);font-size:11px;line-height:1.8}.mail-attachment{display:grid;grid-template-columns:38px 1fr auto;align-items:center;gap:10px;padding:12px;margin-top:14px;border:1px solid rgba(245,200,66,.22);border-radius:12px;background:rgba(245,200,66,.06)}.mail-attachment>span{display:grid;width:36px;height:36px;place-items:center;border-radius:50%;color:#1b0a25;background:var(--color-gold);font-size:10px;font-weight:900}.mail-attachment div{display:flex;flex-direction:column}.mail-attachment strong{font-size:11px}.mail-attachment small{color:var(--color-text-muted);font-size:8px}.mail-attachment button,.delete-mail{padding:7px 10px;border-radius:8px;color:#160823;background:var(--color-gold);font-size:9px;font-weight:900}.mail-attachment button:disabled{opacity:.45}.delete-mail{margin-top:16px;color:#fca5a5;background:rgba(248,113,113,.09)}.detail-empty,.mail-empty{display:flex;min-height:400px;flex-direction:column;align-items:center;justify-content:center;color:var(--color-text-muted);font-size:10px}.detail-empty span{font-size:32px}.detail-empty strong{margin-top:8px;color:#fff;font-size:12px}.gift-toolbar{display:flex;align-items:end;justify-content:space-between;margin:0 0 12px}.gift-toolbar h2{margin:3px 0}.gift-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.gift-card{position:relative;display:grid;grid-template-columns:54px 1fr;gap:14px;padding:18px;border:1px solid rgba(245,200,66,.22);border-radius:17px;background:linear-gradient(145deg,rgba(245,200,66,.08),rgba(168,85,247,.04))}.gift-card.claimed{opacity:.58;filter:saturate(.5)}.gift-mark{display:grid;width:50px;height:50px;place-items:center;border:1px solid rgba(245,200,66,.4);border-radius:15px;color:#241025;background:linear-gradient(145deg,#fde68a,#f5c842);font-weight:1000}.gift-copy small{color:var(--color-gold);font-size:7px;font-weight:900;letter-spacing:.12em}.gift-copy h3{margin:4px 0;font-size:15px}.gift-copy p{margin:0;color:var(--color-text-muted);font-size:9px}.gift-rewards{display:flex;flex-wrap:wrap;gap:5px;margin:10px 0}.gift-rewards span{padding:4px 6px;border-radius:6px;color:#fde68a;background:rgba(245,200,66,.1);font-size:8px}.gift-copy time{color:var(--color-text-muted);font-size:8px}.gift-card>button{grid-column:1/-1;padding:9px;border-radius:9px;color:#1b0a25;background:var(--color-gold);font-size:10px;font-weight:900}.gift-card>button:disabled{color:var(--color-text-muted);background:rgba(255,255,255,.06)}
@media(max-width:800px){.mail-layout{grid-template-columns:1fr}.mail-list{border-right:0}.mail-detail{position:fixed;inset:56px 0 64px;z-index:45;display:none;overflow:auto;background:#10051f}.mail-detail.open{display:block}.detail-close{display:block}.gift-grid{grid-template-columns:1fr}.mail-toolbar{align-items:flex-start;flex-direction:column}.mail-toolbar>div{width:100%}}
@media(max-width:480px){.gift-card{grid-template-columns:45px 1fr;padding:14px}.gift-mark{width:42px;height:42px}}
</style>
